llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Melperone, a close butyrophenone analogue with a basic piperidine and aryl ketone, showed absolute oral bioavailability of 67 ± 28% in healthy volunteers, supporting F ≥ 20% for the query's similar basic ketone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Haloperidol, another butyrophenone antipsychotic with a basic piperidine and aryl ketone, had absolute oral bioavailability values around 35–60% in patients, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Bromperidol, a close haloperidol analogue, showed oral bioavailability of 30% in humans, still above the F ≥ 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Urapidil, a basic amine-containing aryl drug, had oral bioavailability of 78%, supporting high oral absorption for basic amine-containing structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a basic amine with methoxy-substituted aryl and amide functionality, had absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Bunazosin, a basic amine-containing drug, showed absolute oral bioavailability of 44.1%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Raloxifene has very low absolute oral bioavailability of about 2%, but this is driven by extensive phenolic glucuronidation and is structurally distant from the query; it is contradictory but low-weight evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Aniracetam has extremely low oral bioavailability, but it lacks the basic amine and has different metabolic liabilities, making it weakly transferable contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction: high. The query is a basic aryl-butanone with a pyrrolidine, closely resembling butyrophenone antipsychotics. Multiple transferable analogues (melperone, haloperidol, bromperidol) and other basic amine drugs show absolute oral bioavailability of 30–78%, all above 20%. Low-F outliers such as raloxifene and aniracetam are structurally distant and their low bioavailability is explained by specific phenolic glucuronidation or metabolic instability not expected in the query. Therefore F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental pharmacokinetic data for the exact query molecule.",
    "No human data on first-pass metabolism of the trimethoxyphenyl group or pyrrolidine side chain.",
    "Morgan similarities to evidence molecules are modest (<0.36), limiting quantitative transferability.",
    "Potential methoxy-group metabolism and its effect on oral bioavailability is not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

